package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.*;
import com.fasterxml.jackson.databind.deser.impl.PropertyBasedCreator;
import com.fasterxml.jackson.databind.deser.impl.PropertyValueBuffer;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.std.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.KeyDeserializer;
import com.fasterxml.jackson.databind.deser.std.MapDeserializer;
import com.fasterxml.jackson.databind.deser.std.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import java.util.HashSet;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;

public class MapDeserializer_isCachable_TriageGen1Test {

    @Test
    public void testIsCachable_BothNull_ReturnsTrue() {
        // Arrange: _valueTypeDeserializer == null && _ignorableProperties == null
        JavaType mapType = mock(JavaType.class);
        MapDeserializer deserializer = new MapDeserializer(
                mapType, 
                null, 
                null, 
                null, 
                null
        );

        // Act
        boolean result = deserializer.isCachable();

        // Assert
        assertTrue("Should be cachable when both deserializer and ignorable properties are null", result);
    }

    @Test
    public void testIsCachable_ValueTypeDeserializerNotNull_ReturnsFalse() {
        // Arrange: _valueTypeDeserializer != null
        JavaType mapType = mock(JavaType.class);
        TypeDeserializer mockValueTypeDeserializer = mock(TypeDeserializer.class);

        MapDeserializer deserializer = new MapDeserializer(
                mapType, 
                null, 
                null, 
                null, 
                mockValueTypeDeserializer
        );

        // Act
        boolean result = deserializer.isCachable();

        // Assert
        assertFalse("Should not be cachable when _valueTypeDeserializer is not null", result);
    }

    @Test
    public void testIsCachable_IgnorablePropertiesNotNull_ReturnsFalse() {
        // Arrange: _valueTypeDeserializer == null but _ignorableProperties != null
        JavaType mapType = mock(JavaType.class);

        // Using the protected constructor to inject ignorable properties
        // MapDeserializer(MapDeserializer src, KeyDeserializer keyDeser, JsonDeserializer<Object> valueDeser, TypeDeserializer valueTypeDeser, HashSet<String> ignorable)

        // First create a base instance
        MapDeserializer src = new MapDeserializer(mapType, null, null, null, null);

        HashSet<String> ignorable = new HashSet<>();
        ignorable.add("someProperty");

        // We use reflection or the protected constructor if available in the test context
        // Since the prompt provides the protected constructor signature:
        MapDeserializer deserializer = new MapDeserializer(
                src, 
                null, 
                null, 
                null, 
                ignorable
        );

        // Act
        boolean result = deserializer.isCachable();

        // Assert
        assertFalse("Should not be cachable when _ignorableProperties is not null", result);
    }

    @Test
    public void testIsCachable_BothNotNull_ReturnsFalse() {
        // Arrange: Both are not null
        JavaType mapType = mock(JavaType.class);
        TypeDeserializer mockValueTypeDeserializer = mock(TypeDeserializer.class);
        HashSet<String> ignorable = new HashSet<>();
        ignorable.add("someProperty");

        MapDeserializer src = new MapDeserializer(mapType, null, null, null, null);
        MapDeserializer deserializer = new MapDeserializer(
                src, 
                null, 
                null, 
                mockValueTypeDeserializer, 
                ignorable
        );

        // Act
        boolean result = deserializer.isCachable();

        // Assert
        assertFalse("Should not be cachable when both are not null", result);
    }
}
